import React, { useEffect, useMemo, useRef, useState } from "react";
import emailjs from "emailjs-com";
import toast, { Toaster } from "react-hot-toast";
import { FaPaperPlane, FaEnvelope } from "react-icons/fa";
import { socialMediaLinks } from "../../portfolio";
import "./contactform.css";

const SERVICE_ID = "service_xe6alve";
const TEMPLATE_ID = "template_k2u1z0k";
const PUBLIC_KEY = "ANZYSfODJvj2-066t";

/* This template was authored for the JARVIS voice assistant (see
   components/chatbot/EmailAgent.js, which sends the same one) and its
   placeholders are named for that flow, not for this form. sendForm() posts
   the inputs under their own `name` attributes — name / email / subject /
   message — so only `message` ever matched a placeholder and every other line
   in the delivered mail arrived blank.

   These are the names the template actually reads. Until there is a template
   of its own, the form maps onto them explicitly. */
const templateParams = (v) => ({
  from_name: v.name,
  reply_to: v.email,
  // the template renders its subject as "… - {{inquiry_type}}"
  inquiry_type: v.subject,
  message: v.message,
  // the JARVIS flow collects these; a web form does not, and EmailJS renders
  // a missing placeholder as an empty line rather than omitting it
  phone: "Not provided",
  company: "Not provided",
  project: "Not provided",
  timestamp: new Date().toLocaleString("en-IN", { timeZone: "Asia/Kolkata" }),
});

// The form carries `noValidate` so the browser's own error bubbles don't
// clash with the page styling — which means every `required` below is inert
// and validation has to happen here instead.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const validate = (values) => {
  const errors = {};
  if (!values.name) errors.name = "Please tell me your name.";
  else if (values.name.length < 2) errors.name = "That looks too short.";

  if (!values.email) errors.email = "I need an email to reply to.";
  else if (!EMAIL_RE.test(values.email))
    errors.email = "That doesn't look like a valid email.";

  if (!values.subject) errors.subject = "Add a subject so I know what's up.";
  else if (values.subject.length < 3) errors.subject = "That looks too short.";

  if (!values.message) errors.message = "Don't forget the message itself.";
  else if (values.message.length < 10)
    errors.message = "A little more detail would help — 10 characters minimum.";

  return errors;
};

const EMPTY = { name: "", email: "", subject: "", message: "" };

const FIELDS = ["name", "email", "subject", "message"];

/* Per-field completeness, used by the progress rail and the field ticks. It
   reuses validate() rather than restating the rules, so the rail can never
   disagree with what submit will accept. */
const doneMap = (values) => {
  const errs = validate({
    name: values.name.trim(),
    email: values.email.trim(),
    subject: values.subject.trim(),
    message: values.message.trim(),
  });
  return FIELDS.reduce((acc, k) => {
    acc[k] = !errs[k];
    return acc;
  }, {});
};

/* The message as it will actually arrive — which is as an email in his inbox,
   so that is what this shows. It mirrors the form rather than controlling it —
   the inputs stay uncontrolled and submit reads them through FormData — and
   the caret follows whichever field has focus, so typing anywhere on the left
   shows up on the right.

   Deliberately generic mail-client chrome: no Google marks or wordmark. The
   shape is what makes it read as email; the branding would just be somebody
   else's. */
function Mail({ values, focus, state, stamped, receipt, ready }) {
  const bodyRef = useRef(null);
  const [clipped, setClipped] = useState(false);

  /* The body fades out at the bottom when a long message runs past it. That
     fade has to be conditional: applied unconditionally it also dimmed the
     last line of a message that fit perfectly well. */
  useEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    setClipped(el.scrollHeight - el.clientHeight > 2);
  }, [values.message]);

  const time = useMemo(
    () =>
      new Date().toLocaleTimeString("en-IN", {
        hour: "numeric",
        minute: "2-digit",
      }),
    []
  );

  const name = values.name.trim();
  const email = values.email.trim();
  const subject = values.subject.trim();
  const firstName = name.split(/\s+/)[0] || "them";

  /* Initials and a stable colour off the sender's name, the way every mail
     client builds an avatar when there is no photo to use. */
  const initials =
    name
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((w) => w[0].toUpperCase())
      .join("") || "?";

  const hue = useMemo(() => {
    let h = 0;
    for (let i = 0; i < name.length; i++)
      h = (h * 31 + name.charCodeAt(i)) % 360;
    return name ? h : 214;
  }, [name]);

  const caret = (field) =>
    focus === field ? <i className="ct-mail-caret" aria-hidden="true" /> : null;

  return (
    <div className={`ct-mail is-${state}`} aria-hidden="true">
      {/* the rest of the thread, just visible behind the open message */}
      <span className="ct-mail-stack" aria-hidden="true">
        <i />
        <i />
      </span>

      <div className="ct-mail-window">
        {/* the message-view toolbar */}
        <div className="ct-mail-toolbar">
          <span className="ct-mail-tb">
            <i className="ct-mi ct-mi-back" />
            <span className="ct-mail-tb-sep" />
            <i className="ct-mi ct-mi-archive" />
            <i className="ct-mi ct-mi-trash" />
            <i className="ct-mi ct-mi-unread" />
          </span>
          <span className="ct-mail-tb">
            <em className="ct-mail-count">1 of 128</em>
            <i className="ct-mi ct-mi-prev" />
            <i className="ct-mi ct-mi-next" />
          </span>
        </div>

        <div className="ct-mail-head">
          <div className="ct-mail-subject">
            <span className={subject ? "" : "is-empty"}>
              {/* exactly what a mail client shows for an unfilled subject */}
              {subject || "(no subject)"}
              {caret("subject")}
            </span>
            <span className="ct-mail-labels">
              <em>Inbox</em>
              <em className="is-cat">Career</em>
            </span>
          </div>
          {/* the star fills once the message would actually send */}
          <i className={`ct-mail-star${ready ? " is-on" : ""}`} />
        </div>

        <div className="ct-mail-from">
          <span
            className="ct-mail-avatar"
            style={{ "--hue": hue, "--empty": name ? 0 : 1 }}
          >
            {initials}
          </span>
          <span className="ct-mail-who">
            <span className="ct-mail-line">
              <i className="ct-mail-important" />
              <b className={name ? "" : "is-empty"}>
                {name || "your name"}
                {caret("name")}
              </b>
              <em className={email ? "" : "is-empty"}>
                &lt;{email || "your email"}
                {caret("email")}&gt;
              </em>
            </span>
            <span className="ct-mail-to">
              to me
              <i className="ct-mail-chev" />
            </span>
          </span>
          <span className="ct-mail-time">
            {time}
            <em>(just now)</em>
          </span>
        </div>

        <div
          className={`ct-mail-body${clipped ? " is-clipped" : ""}`}
          ref={bodyRef}
        >
          <span className={values.message ? "" : "is-empty"}>
            {values.message || "…and the message itself"}
            {caret("message")}
          </span>
        </div>

        {/* the footer a form-sent mail actually carries */}
        <div className="ct-mail-sig">
          <span className="ct-mail-sig-rule" />
          Sent via the contact form on laxman824.github.io
        </div>

        {/* what happens next: his reply, waiting to be written */}
        <div className="ct-mail-replybar">
          <span className="ct-mail-avatar is-me">KL</span>
          <span className="ct-mail-replyfield">Reply to {firstName}…</span>
          <span className={`ct-mail-delivered${stamped ? " is-set" : ""}`}>
            <i />
            Delivered
          </span>
        </div>
      </div>

      {/* The window leaves the frame on send. Something has to be standing
          where it was, or the send ends on an empty rectangle. */}
      {state === "sent" && (
        <div className="ct-mail-receipt">
          <span className="ct-mail-receipt-tick" aria-hidden="true">
            <i className="ct-mail-ripple" />
          </span>
          <b>Message sent</b>
          <span>Laxman will reach out to you — usually within 24 hours.</span>
          {/* On its own line: inline, a long address broke mid-word
              ("rajesh@gmail." / "com") whatever wrapping rule was used. */}
          {receipt?.email ? (
            <em className="ct-mail-receipt-addr">{receipt.email}</em>
          ) : null}
        </div>
      )}

      <p className={`ct-mail-status${state === "sent" ? " is-ok" : ""}`}>
        {state === "sent"
          ? "Delivered to his inbox"
          : state === "sending"
          ? "Sending…"
          : "Live preview of the email he receives"}
      </p>
    </div>
  );
}

export default function ContactForm({ theme, seed }) {
  const formRef = useRef(null);
  const [sending, setSending] = useState(false);
  const [lastError, setLastError] = useState(null);
  const [errors, setErrors] = useState({});
  const [values, setValues] = useState(EMPTY);
  const [focus, setFocus] = useState(null);
  const [sent, setSent] = useState(false);
  const [receipt, setReceipt] = useState(null);
  /* null when nothing is in the air; otherwise the viewport point the plane
     launches from, so it leaves the button the visitor actually pressed
     rather than a hard-coded corner of the screen. */
  const [flight, setFlight] = useState(null);

  /* Whatever the hero composer captured lands in the message field. The
     inputs are uncontrolled, so the value is written to the node and mirrored
     into state by hand.
     Focus then goes to the name field, which is the next thing missing. */
  useEffect(() => {
    if (!seed?.text) return;
    const f = formRef.current;
    if (!f) return;
    const box = f.elements.message;
    if (box) box.value = seed.text;
    setValues((prev) => ({ ...prev, message: seed.text }));
    setErrors((prev) => ({ ...prev, message: undefined }));
    // after the page's own scroll animation has settled
    const id = setTimeout(() => {
      const first = f.elements.name;
      if (first && !first.value) first.focus({ preventScroll: true });
    }, 900);
    return () => clearTimeout(id);
  }, [seed]);

  const clearError = (name) =>
    setErrors((prev) => (prev[name] ? { ...prev, [name]: undefined } : prev));

  const onField = (e) => {
    const { name, value } = e.target;
    setValues((prev) => ({ ...prev, [name]: value }));
    clearError(name);
  };

  const buildMailto = () => {
    const f = formRef.current;
    if (!f) return `mailto:${socialMediaLinks.gmail}`;
    const data = new FormData(f);
    const params = new URLSearchParams({
      subject: data.get("subject") || "Hello from your portfolio",
      body: `From: ${data.get("name") || ""} <${data.get("email") || ""}>\n\n${
        data.get("message") || ""
      }`,
    });
    return `mailto:${socialMediaLinks.gmail}?${params.toString()}`;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (sending) return;

    const data = new FormData(e.target);
    const next = {
      name: (data.get("name") || "").trim(),
      email: (data.get("email") || "").trim(),
      subject: (data.get("subject") || "").trim(),
      message: (data.get("message") || "").trim(),
    };

    // Honeypot: only a bot fills this, so drop it without feedback
    if ((data.get("website") || "").trim()) return;

    const found = validate(next);
    setErrors(found);
    if (Object.keys(found).length) {
      const firstBad = ["name", "email", "subject", "message"].find(
        (k) => found[k]
      );
      const field = e.target.elements[firstBad];
      if (field) field.focus();
      toast.error("Please fill in the highlighted fields.");
      return;
    }

    setSending(true);
    setLastError(null);

    /* send(), not sendForm(): the payload has to be re-keyed onto the
       template's own placeholder names, which sendForm cannot do. */
    emailjs
      .send(SERVICE_ID, TEMPLATE_ID, templateParams(next), PUBLIC_KEY)
      .then(() => {
        toast.success("Message sent — I'll get back to you soon!");
        setSent(true);
        setReceipt(next);
        const r = e.target
          .querySelector(".contact-form-btn")
          ?.getBoundingClientRect();
        setFlight(
          r
            ? { x: r.left + r.width / 2, y: r.top + r.height / 2 }
            : { x: 0, y: 0 }
        );
        setErrors({});
        /* The letter has to stay on screen long enough to be read as a
           letter: seal sets, then it launches, then the form clears behind
           it. Clearing on the same tick threw the preview away mid-animation
           and the whole thing read as a flicker. */
        setTimeout(() => {
          formRef.current?.reset();
          setValues(EMPTY);
        }, 1500);
        setTimeout(() => setFlight(null), 2200);
        setTimeout(() => {
          setSent(false);
          setReceipt(null);
        }, 6000);
      })
      .catch((err) => {
        const detail =
          (err && (err.text || err.message)) || "Email service unavailable";
        toast.error(`Couldn't send: ${detail}`);
        setLastError(detail);
      })
      .finally(() => setSending(false));
  };

  const mailState = sent ? "sent" : sending ? "sending" : "idle";
  const done = doneMap(values);
  const readyCount = FIELDS.filter((k) => done[k]).length;
  const ready = readyCount === FIELDS.length;

  return (
    <>
      <Toaster position="top-right" />
      <div className="contact-form-shell">
        <div className="contact-form-header">
          <h2 style={{ color: theme?.text }}>I&apos;d love to hear from you</h2>
          <p style={{ color: theme?.secondaryText }}>
            Type on the left — you&apos;ll see the email he gets on the right. I
            usually reply within 24 hours.
          </p>

          {/* How close the message is to sendable. It reads validate(), the
              same function submit uses, so the rail cannot promise something
              the form will then reject. */}
          <div className={`contact-form-progress${ready ? " is-ready" : ""}`}>
            <span
              className="contact-form-progress-track"
              role="progressbar"
              aria-valuemin={0}
              aria-valuemax={FIELDS.length}
              aria-valuenow={readyCount}
              aria-label="Message completeness"
            >
              <span
                className="contact-form-progress-fill"
                style={{ transform: `scaleX(${readyCount / FIELDS.length})` }}
              />
            </span>
            <span className="contact-form-progress-label">
              {ready ? "Ready to send" : `${readyCount} of ${FIELDS.length}`}
            </span>
          </div>
        </div>

        <div className="contact-form-grid">
          <form
            ref={formRef}
            className="contact-form"
            onSubmit={handleSubmit}
            onFocus={(e) => setFocus(e.target.name || null)}
            onBlur={() => setFocus(null)}
            noValidate
          >
            <div className="contact-form-row">
              <div
                className={`contact-form-field${done.name ? " is-done" : ""}${
                  errors.name ? " is-bad" : ""
                }`}
              >
                <input
                  type="text"
                  id="cf-name"
                  name="name"
                  className={`contact-form-text${
                    errors.name ? " invalid" : ""
                  }`}
                  /* a single space, not empty: :placeholder-shown is what
                     drives the label back down into the field */
                  placeholder=" "
                  required
                  autoComplete="name"
                  aria-invalid={!!errors.name}
                  onInput={onField}
                />
                <label htmlFor="cf-name">Your name</label>
                <span className="contact-form-tick" aria-hidden="true" />
                {errors.name && (
                  <span className="contact-form-hint" role="alert">
                    {errors.name}
                  </span>
                )}
              </div>
              <div
                className={`contact-form-field${done.email ? " is-done" : ""}${
                  errors.email ? " is-bad" : ""
                }`}
              >
                <input
                  type="email"
                  id="cf-email"
                  name="email"
                  className={`contact-form-text${
                    errors.email ? " invalid" : ""
                  }`}
                  placeholder=" "
                  required
                  autoComplete="email"
                  aria-invalid={!!errors.email}
                  onInput={onField}
                />
                <label htmlFor="cf-email">Your email</label>
                <span className="contact-form-tick" aria-hidden="true" />
                {errors.email && (
                  <span className="contact-form-hint" role="alert">
                    {errors.email}
                  </span>
                )}
              </div>
            </div>

            <div
              className={`contact-form-field${done.subject ? " is-done" : ""}${
                errors.subject ? " is-bad" : ""
              }`}
            >
              <input
                type="text"
                id="cf-subject"
                name="subject"
                className={`contact-form-text${
                  errors.subject ? " invalid" : ""
                }`}
                placeholder=" "
                required
                aria-invalid={!!errors.subject}
                onInput={onField}
              />
              <label htmlFor="cf-subject">Subject</label>
              <span className="contact-form-tick" aria-hidden="true" />
              {errors.subject && (
                <span className="contact-form-hint" role="alert">
                  {errors.subject}
                </span>
              )}
            </div>

            <div
              className={`contact-form-field is-area${
                done.message ? " is-done" : ""
              }${errors.message ? " is-bad" : ""}`}
            >
              <textarea
                id="cf-message"
                name="message"
                className={`contact-form-text contact-form-textarea${
                  errors.message ? " invalid" : ""
                }`}
                placeholder=" "
                required
                rows={4}
                aria-invalid={!!errors.message}
                onInput={onField}
              />
              <label htmlFor="cf-message">
                What would you like to discuss?
              </label>
              <span className="contact-form-tick" aria-hidden="true" />
              <span className="contact-form-count" aria-hidden="true">
                {values.message.length}
              </span>
              {errors.message && (
                <span className="contact-form-hint" role="alert">
                  {errors.message}
                </span>
              )}
            </div>

            {/* Honeypot for bots — hidden, real users won't touch it */}
            <input
              type="text"
              name="website"
              className="contact-form-honeypot"
              tabIndex={-1}
              autoComplete="off"
              aria-hidden="true"
            />

            <div className="contact-form-actions">
              {/* colour comes from the stylesheet now — an inline background
                  beat the :hover and :disabled rules every time */}
              <button
                type="submit"
                className={`contact-form-btn${sent ? " is-sent" : ""}`}
                disabled={sending}
              >
                <FaPaperPlane aria-hidden="true" />
                {sending ? "Sending…" : sent ? "Sent ✓" : "Send message"}
              </button>

              {lastError && (
                <a
                  className="contact-form-fallback"
                  href={buildMailto()}
                  rel="noopener noreferrer"
                >
                  <FaEnvelope aria-hidden="true" /> Open in your email app
                </a>
              )}
            </div>

            {lastError && (
              <p className="contact-form-error" role="alert">
                The form service hit an error. You can still reach me directly
                at{" "}
                <a href={`mailto:${socialMediaLinks.gmail}`}>
                  {socialMediaLinks.gmail}
                </a>
                .
              </p>
            )}
          </form>

          <Mail
            values={values}
            focus={focus}
            state={mailState}
            stamped={sent}
            receipt={receipt}
            ready={ready}
          />
        </div>

        {/* the plane only exists while it is in the air */}
        {flight && (
          <span
            className="ct-plane"
            aria-hidden="true"
            style={{ left: `${flight.x}px`, top: `${flight.y}px` }}
          />
        )}
      </div>
    </>
  );
}
