function Contact(props) {
  const theme = props.theme;
  const formRef = useRef(null);
  const cursorRef = useRef(null);
  const rootRef = useRef(null);
  const [copied, setCopied] = useState(false);
  /* What the hero composer captured, handed to the form below. The key is
     what makes a repeat send land — the same text twice is still a new
     instruction to refill and refocus. */
  const [seed, setSeed] = useState(null);

  /* window.scrollTo and scrollIntoView are both no-ops sitewide — html and
     body carry overflow-x: clip — so the scroll has to be animated by hand.
     This is why the old "Send me a message" button did nothing at all. */
  const scrollToY = useCallback((targetY) => {
    const root = document.documentElement;
    const start = root.scrollTop;
    const dist = targetY - start;
    if (Math.abs(dist) < 2) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      root.scrollTop = targetY;
      return;
    }
    const t0 = performance.now();
    const dur = Math.min(900, 320 + Math.abs(dist) * 0.22);
    const step = (t) => {
      const p = Math.min(1, (t - t0) / dur);
      const e = 1 - Math.pow(1 - p, 3); // easeOutCubic
      root.scrollTop = start + dist * e;
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, []);

  const scrollToForm = useCallback(() => {
    const el = formRef.current;
    if (!el) return;
    const root = document.documentElement;
    scrollToY(el.getBoundingClientRect().top + root.scrollTop - 96);
  }, [scrollToY]);

  const toTop = useCallback(() => scrollToY(0), [scrollToY]);

  const sendDraft = useCallback(
    (text) => {
      setSeed({ text, key: Date.now() });
      scrollToForm();
    },
    [scrollToForm]
  );

  const copyEmail = useCallback(() => {
    const address = socialMediaLinks.gmail;
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(address).then(
        () => {
          setCopied(true);
          toast.success(`Copied ${address}`);
          setTimeout(() => setCopied(false), 1800);
        },
        () => toast(address)
      );
    } else {
      toast(address);
    }
  }, []);

  /* Cursor-following spotlight and a couple of degrees of tilt, shared by the
     portrait and the channel rows. Past about 4deg the type starts to smear. */
  const onSpot = useCallback((e) => {
    if (window.innerWidth < 769) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width;
    const y = (e.clientY - r.top) / r.height;
    el.style.setProperty("--mx", `${(x * 100).toFixed(1)}%`);
    el.style.setProperty("--my", `${(y * 100).toFixed(1)}%`);
    el.style.setProperty("--ry", `${((x - 0.5) * 3).toFixed(2)}deg`);
    el.style.setProperty("--rx", `${((0.5 - y) * 2.2).toFixed(2)}deg`);
    /* Parallax: the halo trails the plate and the tag leads it, so the three
       read as objects at different depths rather than one flat picture. */
    el.style.setProperty("--px", `${(x - 0.5).toFixed(3)}`);
    el.style.setProperty("--py", `${(y - 0.5).toFixed(3)}`);
  }, []);

  const offSpot = useCallback((e) => {
    const el = e.currentTarget;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
    el.style.setProperty("--px", "0");
    el.style.setProperty("--py", "0");
  }, []);

  /* Reveal on scroll. react-reveal (still a dependency here) mounts its
     children hidden and relies on legacy lifecycles; an observer setting one
     class does the same job without shipping a second animation runtime. */
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const targets = Array.from(root.querySelectorAll("[data-reveal]"));
    if (typeof IntersectionObserver === "undefined") {
      targets.forEach((el) => el.classList.add("is-in"));
      return undefined;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add("is-in");
          obs.unobserve(entry.target);
        });
      },
      { rootMargin: "0px 0px -12% 0px", threshold: 0.08 }
    );
    targets.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
  }, []);

  /* Magnetism. Every [data-magnet] control leans toward the pointer once it
     is within reach, and springs back when it leaves — one window listener
     measuring all of them, rather than a listener per button. */
  useEffect(() => {
    if (window.matchMedia("(pointer: coarse)").matches) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    const root = rootRef.current;
    if (!root) return undefined;

    let pending = false;
    let px = 0;
    let py = 0;
    const REACH = 88; // px of empty space around a control that still pulls
    const PULL = 0.32; // fraction of the distance the control travels

    const paint = () => {
      pending = false;
      root.querySelectorAll("[data-magnet]").forEach((el) => {
        const r = el.getBoundingClientRect();
        if (!r.width) return;
        const dx = px - (r.left + r.width / 2);
        const dy = py - (r.top + r.height / 2);
        const reach = Math.max(r.width, r.height) / 2 + REACH;
        const dist = Math.hypot(dx, dy);
        const on = el.classList.contains("is-magnet");
        if (dist < reach) {
          const k = (1 - dist / reach) * PULL;
          el.style.setProperty("--mag-x", `${(dx * k).toFixed(1)}px`);
          el.style.setProperty("--mag-y", `${(dy * k).toFixed(1)}px`);
          if (!on) el.classList.add("is-magnet");
        } else if (on) {
          el.style.setProperty("--mag-x", "0px");
          el.style.setProperty("--mag-y", "0px");
          el.classList.remove("is-magnet");
        }
      });
    };

    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!pending) {
        pending = true;
        requestAnimationFrame(paint);
      }
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => window.removeEventListener("mousemove", onMove);
  }, []);

  /* Keyboard shortcuts. The whole page exists to get one message written, so
     the two things worth a single keystroke are writing it and taking the
     address away with you. */
  useEffect(() => {
    const onKey = (e) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const t = e.target;
      if (
        t &&
        (t.tagName === "INPUT" ||
          t.tagName === "TEXTAREA" ||
          t.isContentEditable)
      )
        return;
      const k = e.key.toLowerCase();
      if (k === "m") {
        e.preventDefault();
        scrollToForm();
        // after the scroll settles, or the browser yanks it back mid-flight
        setTimeout(() => {
          const first = document.querySelector('.contact-form [name="name"]');
          if (first) first.focus({ preventScroll: true });
        }, 820);
      } else if (k === "c") {
        e.preventDefault();
        copyEmail();
      } else if (k === "t") {
        e.preventDefault();
        toTop();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [scrollToForm, copyEmail, toTop]);

  /* Page-wide torch, picking up the tint of whatever [data-torch] element it
     happens to be over. */
  useEffect(() => {
    let pending = false;
    let px = 0;
    let py = 0;
    const paint = () => {
      pending = false;
      const c = cursorRef.current;
      if (!c) return;
      c.style.setProperty("--cx", `${px}px`);
      c.style.setProperty("--cy", `${py}px`);
      const host = document.elementFromPoint(px, py);
      const tinted = host && host.closest("[data-torch]");
      c.style.setProperty(
        "--torch",
        tinted ? tinted.dataset.torch : theme.accentColor
      );
      c.style.setProperty("--torch-r", tinted ? "520px" : "760px");
    };
    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!pending) {
        pending = true;
        requestAnimationFrame(paint);
      }
      if (cursorRef.current) cursorRef.current.classList.add("is-on");
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => window.removeEventListener("mousemove", onMove);
  }, [theme.accentColor]);

  return (
    <div className="contact-main" data-theme={theme?.name}>
      <Header theme={theme} setTheme={props.setTheme} />

      <div
        ref={rootRef}
        className={`ct is-${theme?.name === "light" ? "light" : "dark"}`}
        style={{
          "--fg": theme.text,
          "--muted": theme.secondaryText,
          "--accent": theme.accentColor,
          "--accent2": theme.accentBright,
          "--bg": theme.body,
        }}
      >
        <div className="ct-cursor" ref={cursorRef} aria-hidden="true" />

        {/* ============================================== hero */}
        <section className="ct-hero">
          <div className="ct-hero-text" data-reveal>
            <p className="ct-eyebrow">
              <i />
              Get in touch
            </p>

            <h1
              className="ct-title"
              aria-label="Tell me what you're building. I'll tell you if I can help."
            >
              <span aria-hidden="true">
                Tell me what
                <br />
                you&apos;re <LivingWord text="building." className="hl" />
                <br />
                <span className="dim">I&apos;ll tell you if I can help.</span>
              </span>
            </h1>

            <p className="ct-lede">{ContactData["description"]}</p>

            <div className="ct-facts">
              <p>
                <b>&lt; 24h</b>
                <span>typical reply</span>
              </p>
              <p className="ct-fact-clock">
                <TimeDial />
              </p>
              <p>
                <b>Chennai</b>
                <span>IST · remote-friendly</span>
              </p>
            </div>

            {/* start writing here, not two screens down */}
            <HeroComposer onSend={sendDraft} />

            {/* The composer above is the primary action now, so this row is
                just the other way of reaching him — no second button saying
                the same thing as the field. */}
            <div className="ct-actions">
              <button
                type="button"
                className={`ct-cta${copied ? " is-copied" : ""}`}
                onClick={copyEmail}
                data-magnet
              >
                <FaEnvelope aria-hidden="true" />
                {copied ? "Address copied ✓" : socialMediaLinks.gmail}
              </button>
            </div>

            <p className="ct-keys">
              <kbd>M</kbd> jumps to the full form · <kbd>C</kbd> copies the
              address
            </p>
          </div>

          {/* The right-hand column: the portrait, then the action buttons in
              the space under it. On a laptop that space was empty while the
              buttons sat below the fold in the copy column. */}
          <div className="ct-hero-side" data-reveal>
            {/* the portrait, mounted rather than floating: a plate with its
                own warm halo, an availability tag pinned to the corner, and
                the caption that used to be scattered across three chip
                strips */}
            <figure
              className="ct-portrait"
              data-torch="#B4593A"
              onMouseMove={onSpot}
              onMouseLeave={offSpot}
            >
              <span className="ct-portrait-halo" aria-hidden="true" />
              <span className="ct-portrait-plate">
                <span className="ct-rim" aria-hidden="true" />
                <span className="ct-spot" aria-hidden="true" />
                <img src={portrait} alt="K Laxman" />
                {/* inside the plate — parked below it, it landed on top of the
                  caption's second line */}
                <span className="ct-status">
                  <i className="ct-status-dot" aria-hidden="true" />
                  Open to opportunities
                </span>
              </span>
              <figcaption>
                <b>K Laxman</b>
                <span>
                  Senior AI Engineer, CAMS · M.Tech &amp; B.Tech, IIT Delhi
                </span>
              </figcaption>
            </figure>

            {/* The original gradient action buttons, kept as they were. */}
            <div className="button-container">
              <a
                className="general-btn"
                href={resumeDownloadUrl()}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="See my Résumé"
                title="See my Résumé"
              >
                <FaFileAlt aria-hidden="true" /> Résumé
              </a>
              <Link
                className="github-btn"
                to="/github"
                aria-label="GitHub Contributions"
                title="GitHub Contributions"
              >
                <FaGithub className="github-icon" />
                GitHub
              </Link>
              <Link className="button-contact" to="/projects">
                Recent Work
              </Link>
            </div>
          </div>
        </section>

        {/* ============================================ channels */}
        <section className="ct-block" data-reveal>
          <p className="ct-section">Direct lines</p>
          <div className="ct-rail">
            {CHANNELS.map((c) => (
              <a
                key={c.name}
                className="ct-line"
                href={c.href}
                target={c.href.startsWith("mailto:") ? "_self" : "_blank"}
                rel="noopener noreferrer"
                style={{ "--ca": c.accent }}
                data-torch={c.accent}
                onMouseMove={onSpot}
                onMouseLeave={offSpot}
                onClick={c.copy ? copyEmail : undefined}
              >
                <span className="ct-rim" aria-hidden="true" />
                <span className="ct-spot" aria-hidden="true" />
                <span className="ct-line-mark" aria-hidden="true">
                  {c.icon}
                </span>
                <span className="ct-line-text">
                  <b>{c.name}</b>
                  <em>{c.handle}</em>
                </span>
                <span className="ct-line-note">{c.note}</span>
                <span className="ct-line-go" aria-hidden="true">
                  ↗
                </span>
              </a>
            ))}
          </div>
        </section>

        {/* ============================================== brief */}
        {/* A spread, not a paragraph: the ask on the left, the four things it
            actually means on the right. The right half of this section used
            to be empty while the four focus areas sat as bare text under the
            headline. */}
        <section className="ct-block ct-brief" data-reveal>
          <div className="ct-brief-grid">
            <div className="ct-brief-lead">
              <p className="ct-section">What I&apos;m looking for</p>
              <h2 className="ct-brief-title">
                Roles where I ship production AI, and grow toward{" "}
                <span className="hl">technical leadership.</span>
              </h2>
              <p className="ct-brief-note">
                Based in Chennai, from Hyderabad, and actively looking at{" "}
                <strong>Hyderabad</strong> and <strong>Bangalore</strong>.
                Remote and hybrid both work.
              </p>
              <a className="ct-brief-cta" href={greetingResume} download>
                <span>Full history in the résumé</span>
                <em aria-hidden="true">↗</em>
              </a>
            </div>

            <ol className="ct-focus">
              {LOOKING_FOR.map((f, i) => (
                <li
                  className="ct-focus-row"
                  key={f.title}
                  style={{ "--ca": f.accent }}
                  data-torch={f.accent}
                  onMouseMove={onSpot}
                  onMouseLeave={offSpot}
                >
                  <span className="ct-rim" aria-hidden="true" />
                  <span className="ct-spot" aria-hidden="true" />
                  <span className="ct-focus-no" aria-hidden="true">
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  <span className="ct-focus-body">
                    <b>{f.title}</b>
                    <span>{f.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </div>
        </section>

        {/* =============================================== form */}
        <section className="ct-block ct-form-block" ref={formRef} data-reveal>
          <p className="ct-section">Send it here</p>
          <ContactForm theme={theme} seed={seed} />
        </section>

        {/* ======================================= testimonials */}
        <section className="ct-block ct-testimonials" data-reveal>
          <TestimonialCards theme={theme} />
        </section>

        {/* ================================================ faq */}
        {inlineFaqs.length > 0 && (
          <section className="ct-block ct-faq" data-reveal>
            <p className="ct-section">Quick answers</p>
            <div className="ct-faq-list">
              {inlineFaqs.map((f) => (
                <FaqRow
                  key={f.question}
                  question={f.question}
                  answer={f.answer}
                />
              ))}
            </div>
            <Link to="/faq" className="ct-faq-more">
              Everything else
              <em>→</em>
            </Link>
          </section>
        )}

        {/* ============================================== where */}
        <section className="ct-block ct-where" data-reveal>
          <p className="ct-section">Where I am</p>
          <div className="ct-where-row">
            <div className="ct-where-text">
              <h2>
                Chennai today.
                <br />
                <span className="hl">Hyderabad or Bangalore next.</span>
              </h2>
              <p>
                At CAMS in Chennai, native to Hyderabad, and open to moving for
                the right team — or to staying remote for it.
              </p>
            </div>
            <div className="ct-map">
              <iframe
                title="Hyderabad — preferred base"
                src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d243650.96891459517!2d78.24323405!3d17.412281850000002!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bcb99daeaebd2c7%3A0xae93b29a20e27434!2sHyderabad%2C%20Telangana!5e0!3m2!1sen!2sin!4v1716172800000!5m2!1sen!2sin"
                width="100%"
                height="320"
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
              />
              <span className="ct-map-veil" aria-hidden="true" />
            </div>
          </div>
        </section>

        {/* ================================================ end */}
        <footer className="ct-end" data-reveal>
          <h2 className="ct-end-title">
            Still reading?
            <br />
            <span>Then we should probably talk.</span>
          </h2>
          <div className="ct-end-actions">
            <button
              type="button"
              className="ct-cta is-primary"
              onClick={scrollToForm}
              data-magnet
            >
              Start a message
              <em>↑</em>
            </button>
            <a
              className="ct-cta"
              href={`mailto:${socialMediaLinks.gmail}`}
              data-magnet
            >
              Or just email me
            </a>
          </div>
          <button type="button" className="ct-top" onClick={toTop}>
            <span aria-hidden="true">↑</span> Back to top
          </button>
        </footer>
      </div>

      <Footer theme={props.theme} onToggle={props.onToggle} />
    </div>
  );
}

export default Contact;
